import os, json, zipfile, pathlib, re
import xml.etree.ElementTree as ET

template_path = '/root/inventory_report_template.hwpx'
json_path = '/root/inventory_data.json'
extracted_dir = pathlib.Path('/tmp/hwpx_extracted')
output_path = '/root/inventory_report_ready.hwpx'

# fresh extract
if extracted_dir.exists():
    for p in sorted(extracted_dir.rglob('*'), reverse=True):
        if p.is_file() or p.is_symlink():
            p.unlink()
        elif p.is_dir():
            try:
                p.rmdir()
            except OSError:
                pass
else:
    extracted_dir.mkdir(parents=True)

with zipfile.ZipFile(template_path, 'r') as z:
    z.extractall(extracted_dir)

with open(json_path, 'r', encoding='utf-8') as f:
    data = json.load(f)

# helper to get localname

def localname(tag: str) -> str:
    if tag.startswith('{'):
        return tag.split('}',1)[1]
    return tag

# replacement regex
ph_re = re.compile(r'\{\{([^}]+)\}\}')

missing_keys = set()
seen_placeholders = set()

def replace_placeholders(s: str) -> str:
    def sub(m):
        key = m.group(1)
        seen_placeholders.add(key)
        if key not in data:
            missing_keys.add(key)
            return m.group(0)
        v = data[key]
        return '' if v is None else str(v)
    return ph_re.sub(sub, s)

# Find namespace URI used for hp prefix (so we preserve the prefix on write)
# We do this per-file after parsing.

layout_localnames = {'linesegarray', 'lineSegArray', 'lineseg', 'lineSeg'}

# Count paragraphs before/after
para_counts_before = {}
para_counts_after = {}

xml_files = sorted(extracted_dir.rglob('*.xml'))
for xml_path in xml_files:
    tree = ET.parse(xml_path)
    root = tree.getroot()

    # register namespaces present in the document so prefixes stay stable.
    # The template uses 'hp' prefix for HWPML.
    if root.tag.startswith('{'):
        uri = root.tag.split('}',1)[0][1:]
        ET.register_namespace('hp', uri)

    paras_before = sum(1 for el in root.iter() if localname(el.tag) == 'p')
    para_counts_before[str(xml_path)] = paras_before

    # Walk paragraphs, replace in text/tail nodes, and clear layout caches for modified paragraphs
    for p in [el for el in root.iter() if localname(el.tag) == 'p']:
        changed = False

        # Replace in all descendant nodes' .text and .tail
        for el in p.iter():
            if el.text and '{{' in el.text:
                new = replace_placeholders(el.text)
                if new != el.text:
                    el.text = new
                    changed = True
            if el.tail and '{{' in el.tail:
                new = replace_placeholders(el.tail)
                if new != el.tail:
                    el.tail = new
                    changed = True

        if changed:
            # Remove layout-cache elements (linesegarray/lineseg etc) under this paragraph
            def prune(parent):
                for child in list(parent):
                    if localname(child.tag) in layout_localnames:
                        parent.remove(child)
                    else:
                        prune(child)
            prune(p)

    paras_after = sum(1 for el in root.iter() if localname(el.tag) == 'p')
    para_counts_after[str(xml_path)] = paras_after

    tree.write(xml_path, encoding='utf-8', xml_declaration=True)

if missing_keys:
    raise SystemExit(f'Missing JSON keys for placeholders: {sorted(missing_keys)}')

# Verify paragraph counts unchanged
for path, before in para_counts_before.items():
    after = para_counts_after[path]
    if before != after:
        raise SystemExit(f'Paragraph count changed in {path}: before {before}, after {after}')

# Verify no placeholders remain
remaining = []
for xml_path in xml_files:
    txt = xml_path.read_text(encoding='utf-8', errors='replace')
    if '{{' in txt:
        remaining.append(str(xml_path))

if remaining:
    raise SystemExit(f'Placeholders remain in: {remaining}')

# Repackage
if os.path.exists(output_path):
    os.unlink(output_path)

with zipfile.ZipFile(output_path, 'w', compression=zipfile.ZIP_DEFLATED) as zf:
    # HWPX typically resembles a zip; store mimetype uncompressed first if present
    mimetype_path = extracted_dir / 'mimetype'
    if mimetype_path.exists():
        zf.write(mimetype_path, 'mimetype', compress_type=zipfile.ZIP_STORED)

    for root_dir, dirs, files in os.walk(extracted_dir):
        for f in files:
            full = os.path.join(root_dir, f)
            arcname = os.path.relpath(full, extracted_dir)
            if arcname == 'mimetype':
                continue
            zf.write(full, arcname)

print('OK')
print('seen placeholders:', sorted(seen_placeholders))
print('wrote:', output_path)
